    Bug 1876127 - Fix test_qp_chunking.js body comparison failing on Windows (LF vs CRLF). r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D311809

diff --git a/mailnews/mime/test/unit/test_qp_chunking.js b/mailnews/mime/test/unit/test_qp_chunking.js
index 6df2c3e2cb6..c7b40371751 100644
--- a/mailnews/mime/test/unit/test_qp_chunking.js
+++ b/mailnews/mime/test/unit/test_qp_chunking.js
@@ -111,6 +111,9 @@ async function renderMessage(chunks) {
 }

 function getRenderedBody(rendered) {
+  // The emitter terminates lines with MSG_LINEBREAK, which is CRLF on
+  // Windows. Normalize so we can assert using LF cross-platform.
+  rendered = rendered.replaceAll("\r\n", "\n");
   const match = /^<pre[^>]*>\n([\s\S]*)\n<\/pre>$/.exec(rendered);
   Assert.ok(match, "quoting should render the decoded message body");
   return match[1];
